mapper.select:
SELECT COUNT(*) FROM asgn.asgn x JOIN asgn.asgn a ON a.asgn_id=#{id}
WHERE x.asgn_id!=a.asgn_id AND x.dev_id=a.dev_id AND x.prj_id=a.prj_id
  AND x.asgn_stts_cd!='CANCELLED' AND x.bgn_dt<=#{end} AND x.end_dt>=#{start}

mapper.delete:
DELETE FROM asgn.asgn_mth m USING asgn.asgn a WHERE a.asgn_id=m.asgn_id AND a.asgn_id=#{id}
  AND (m.work_ym<TO_CHAR(a.bgn_dt,'YYYY-MM') OR m.work_ym>TO_CHAR(a.end_dt,'YYYY-MM'))
  AND NOT EXISTS(SELECT 1 FROM fin.mth_cls c WHERE c.cls_ym=m.work_ym AND c.cls_stts_cd='CLOSED')
